const body = $input.first().json;
const esCallback = Boolean(body.callback_query);
const chatId = esCallback ? body.callback_query.message.chat.id : body.message.chat.id;
const telegramId = esCallback ? body.callback_query.from.id : body.message.from.id;
const texto = esCallback ? '' : (body.message.text || '').trim();
const callbackData = esCallback ? body.callback_query.data : '';
const nombreCompleto = esCallback ? `${body.callback_query.from.first_name || ''} ${body.callback_query.from.last_name || ''}`.trim() : `${body.message.from.first_name || ''} ${body.message.from.last_name || ''}`.trim();
return [{ json: { chatId, telegramId, texto, callbackData, esCallback, nombreCompleto } }];

const entrada = $('Normalizar Update').first().json;
const primerItem = items.length > 0 ? items[0].json : null;
const tieneDatos = primerItem && (primerItem.telegram_id || primerItem.pantalla_actual);
const sesionExistente = tieneDatos ? primerItem : null;

const texto = (entrada.texto || '').trim().toLowerCase();
const cb = entrada.callbackData || '';

let carrito = [];
try {
  carrito = (sesionExistente && sesionExistente.carrito_temporal)
    ? JSON.parse(sesionExistente.carrito_temporal)
    : [];
} catch (e) {
  carrito = [];
}

let pantallaActual = 'inicio';
if (texto === '/start' || texto === 'start' || texto === 'hola' || texto === 'menu' || cb === 'cat_volver') {
  pantallaActual = 'inicio';
  if (texto === '/start') carrito = [];
} else if (cb.startsWith('cat_')) {
  pantallaActual = 'categoria';
} else if (cb.startsWith('prod_') || (sesionExistente?.pantalla_actual === 'producto' && !isNaN(parseInt(texto, 10)))) {
  pantallaActual = 'producto';
} else if (cb.startsWith('qty_') || (sesionExistente?.pantalla_actual === 'cantidad' && !isNaN(parseInt(texto, 10)))) {
  pantallaActual = 'cantidad';
} else if (cb.startsWith('carrito_')) {
  pantallaActual = 'carrito';
} else if (cb.startsWith('confirmar_')) {
  pantallaActual = 'confirmar';
} else if (sesionExistente && sesionExistente.pantalla_actual) {
  pantallaActual = sesionExistente.pantalla_actual;
}

return [{
  json: {
    ...entrada,
    existeSesion: Boolean(sesionExistente),
    pantallaActual,
    carrito,
    categoriaTemp: sesionExistente ? (sesionExistente.categoria_temp || '') : '',
    productoTemp: sesionExistente ? (sesionExistente.producto_temp || '') : ''
  }
}];

const entrada = $('Procesar Sesion').first().json;
const categoria = entrada.callbackData.replace('cat_', '');
return [{ json: { ...entrada, categoriaElegida: categoria } }];

function getField(obj, keys) {
  for (const k of keys) {
    for (const prop in obj) {
      if (prop.trim().toLowerCase() === k.toLowerCase() && obj[prop] !== undefined && obj[prop] !== '') {
        return obj[prop];
      }
    }
  }
  return undefined;
}

const rawItems = items.map(i => i.json).filter(i => Object.keys(i).length > 0);
const categoria = $('Extraer Categoria').first().json.categoriaElegida;

const productos = [];
rawItems.forEach((p, idx) => {
  const nombre = getField(p, ['nombre', 'producto', 'name', 'articulo', 'descripcion']);
  if (nombre) {
    const id = getField(p, ['id_producto', 'id', 'codigo', 'ID_PRODUCTO', 'ID']) || String(idx + 1);
    const precioRaw = getField(p, ['precio', 'price', 'valor', 'costo']) || 0;
    const precio = Number(String(precioRaw).replace(/[^0-9.]/g, '')) || 0;
    productos.push({ id_producto: String(id), nombre: String(nombre), precio });
  }
});

let textoMenu = `🍽️ *Menú de ${categoria}:*\n\n`;
let tieneProductos = productos.length > 0;
if (!tieneProductos) {
  textoMenu += 'No hay productos registrados en esta categoría.\nRevisa en tu hoja MENU que la columna categoria tenga exactamente: ' + categoria;
} else {
  productos.forEach((p, idx) => {
    textoMenu += `*${idx + 1}.* ${p.nombre} — $${p.precio}\n`;
  });
  textoMenu += '\n👉 *Selecciona el número del producto:*';
}

return [{
  json: {
    chatId: $('Extraer Categoria').first().json.chatId,
    telegramId: $('Extraer Categoria').first().json.telegramId,
    carrito: $('Extraer Categoria').first().json.carrito,
    categoriaElegida: categoria,
    tieneProductos,
    listaProductos: JSON.stringify(productos),
    textoMenu
  }
}];

const entrada = $('Procesar Sesion').first().json;
const raw = entrada.callbackData || entrada.texto || '';
const valor = raw.replace('prod_', '').trim();
const num = parseInt(valor, 10);

let productos = [];
try {
  productos = JSON.parse(entrada.productoTemp || '[]');
} catch (e) {
  productos = [];
}

let prodElegido = null;
if (!isNaN(num) && num >= 1 && num <= productos.length) {
  prodElegido = productos[num - 1];
} else if (productos.some(p => p.id_producto === valor)) {
  prodElegido = productos.find(p => p.id_producto === valor);
} else if (productos.length > 0) {
  prodElegido = productos[0];
} else {
  prodElegido = { id_producto: valor, nombre: 'Producto ' + valor, precio: 0 };
}

return [{
  json: {
    ...entrada,
    productoTemp: JSON.stringify(prodElegido)
  }
}];

const sesion = $('Procesar Sesion').first().json;
const raw = sesion.callbackData || sesion.texto || '';
const cantidad = Number(raw.replace('qty_', '')) || 1;

// 1. Intentar obtener de Leer Producto Elegido si vino con datos reales
let producto = items.length > 0 && items[0].json && items[0].json.nombre ? items[0].json : null;

// 2. Si no, recuperar el JSON del producto que guardamos en la sesión
if (!producto) {
  try {
    producto = JSON.parse(sesion.productoTemp || '{}');
  } catch (e) {
    producto = { id_producto: '1', nombre: 'Producto', precio: 0 };
  }
}

const nombre = producto.nombre || 'Producto';
const precio = Number(producto.precio) || 0;
const id_producto = producto.id_producto || '1';

const carrito = [...(sesion.carrito || [])];
const existente = carrito.find((it) => String(it.id_producto) === String(id_producto));
if (existente) {
  existente.cantidad += cantidad;
} else {
  carrito.push({ id_producto, nombre, precio, cantidad });
}

const total = carrito.reduce((acc, i) => acc + (Number(i.precio) * Number(i.cantidad)), 0);

return [{ json: { ...sesion, carrito, total } }];

const sesion = $('Procesar Sesion').first().json;
const idPedido = 'PED-' + Date.now();
const total = sesion.carrito.reduce((a, i) => a + i.precio * i.cantidad, 0);
const detalles = sesion.carrito.map(i => `${i.cantidad}x ${i.nombre}`).join(', ');
const ahora = new Date();
return [{
  json: {
    chatId: sesion.chatId,
    telegramId: sesion.telegramId,
    id_usuario: sesion.telegramId,
    idPedido,
    id_pedido: idPedido,
    detalles,
    total,
    fecha: ahora.toISOString().split('T')[0],
    hora: ahora.toTimeString().split(' ')[0],
    estado: 'En preparación',
    carrito: sesion.carrito
  }
}];

